$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='content/kinetics/chainConveyor/ChainConveyorInteractionHandler.java';changes=@([pscustomobject]@{from='import com.simibubi.create.AllTags.AllItemTags;';to="import com.simibubi.create.AllTags.AllItemTags;`nimport com.simibubi.create.CreateClient;"},[pscustomobject]@{from='import com.simibubi.create.foundation.outliner.Outliner;';to=''},[pscustomobject]@{from='Outliner.getInstance()';to='CreateClient.OUTLINER'});status='Original Chain Conveyor interaction preview retained through the Fabric baseline client outliner.'},
 [pscustomobject]@{rel='content/kinetics/chainConveyor/ChainConveyorRenderer.java';changes=@([pscustomobject]@{from='Matrix3f matrix3f = posestack$pose.normal();';to='PoseStack.Pose normalPose = posestack$pose;'},[pscustomobject]@{from='renderQuad(matrix4f, matrix3f,';to='renderQuad(matrix4f, normalPose,'},[pscustomobject]@{from='private static void renderQuad(Matrix4f pPose, Matrix3f pNormal,';to='private static void renderQuad(Matrix4f pPose, PoseStack.Pose pNormal,'},[pscustomobject]@{from='private static void addVertex(Matrix4f pPose, Matrix3f pNormal,';to='private static void addVertex(Matrix4f pPose, PoseStack.Pose pNormal,'});status='Original Chain Conveyor chain-quad rendering adapted to Minecraft 1.21.1 vertex normal API.'},
 [pscustomobject]@{rel='content/kinetics/chainConveyor/ServerboundChainConveyorRidingPacket.java';changes=@([pscustomobject]@{from="`n`t`tsender.connection.aboveGroundVehicleTickCount = 0;";to=''});status='Original chain-riding anti-flight reset retained through the existing Fabric accessor only.'},
 [pscustomobject]@{rel='content/logistics/packagePort/postbox/PostboxRenderer.java';changes=@([pscustomobject]@{from='.toYRot()), Axis.YP);';to='.toYRot()));'});status='Original Postbox flag and hover-label renderer adapted to Fabric Flywheel transforms.'},
 [pscustomobject]@{rel='content/logistics/packagerLink/WiFiParticle.java';changes=@([pscustomobject]@{from="`n`t`tthis.stoppedByCollision = true; // disable movement";to=''});status='Original stationary WiFi particle retained through its overridden tick method; removed inaccessible vanilla movement flag assignment.'}
)
foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);foreach($c in $t.changes){if(-not$x.Contains($c.from)){throw "Client/network anchor missing in $($t.rel): $($c.from)"};$x=$x.Replace($c.from,$c.to)};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;if($e.PSObject.Properties.Name -contains 'status'){$e.status=$t.status}else{$e|Add-Member -NotePropertyName status -NotePropertyValue $t.status}}
$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Cleaned the native client/network API tail.'
